/* @lc app=leetcode id=3770 lang=kotlin */ class Solution { fun largestPrime(n: Int): Int = BooleanArray(n + 1) { it >= 2 }.also { s -> (2..Math.sqrt(n.toDouble()).toInt()).forEach { i -> if (s[i]) (i * i..n step i).forEach { s[it] = false } } }.let { sv -> (2..n).filter { sv[it] }.runningFold(0) { a, b -> a + b }.drop(1).takeWhile { it <= n }.filter { sv[it] }.maxOrNull() ?: 0 } }